108	    /**
109	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
110	     * code, the literal {@code '-M'}, and the last two digits of the fiscal year derived from
111	     * the (business-day-adjusted) registrationDate. Returns {@code null} unless both the
112	     * customer code and registration date are present.
113	     */
