121	    /**
122	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}: the literal {@code 'FY'}
123	     * and the last two digits of the fiscal year derived from the (business-day-adjusted)
124	     * registrationDate. The fiscal year starts on 1 July. Returns {@code null} when no registration
125	     * date is present.
126	     */
