134	    /**
135	     * Formats the last two digits (zero-padded) of the fiscal year that {@code date} falls in.
136	     */
137	    private String fiscalYearYY(LocalDate date) {
138	        return String.format("%02d", RegistrationDateNormalizer.fiscalYear(date) % 100);
