143	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
144	     */
145	    default Integer checkDigit(Owner owner) {
146	        if (owner == null || owner.getCustomerCode() == null) {
147	            return null;
148	        }
149	        String code = owner.getCustomerCode();
150	        int sum = 0;
151	        boolean dbl = true;
152	        for (int i = code.length() - 1; i >= 0; i--) {
153	            char c = code.charAt(i);
154	            if (c < '0' || c > '9') {
155	                continue;
156	            }
157	            int d = c - '0';
158	            if (dbl) {
159	                d *= 2;
160	                if (d > 9) {
161	                    d -= 9;
162	                }
163	            }
164	            sum += d;
165	            dbl = !dbl;
166	        }
167	        return (10 - (sum % 10)) % 10;
168	    }
