170	    /**
171	     * Computes the owner's membership points. Starts at {@code 0}; adds {@code 2} when an email
172	     * address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0);
173	     * adds {@code 2} when the owner belongs to a household of {@code 3} or more members; adds
174	     * {@code 3} when the owner's tenure exceeds one fiscal year, where tenure is the number of
175	     * elapsed fiscal years (the current fiscal year minus the registration fiscal year).
176	     */
177	    default Integer membershipPoints(Owner owner) {
178	        if (owner == null) {
179	            return null;
180	        }
181	        int points = 0;
182	        String email = owner.getEmail();
183	        if (email != null && !email.isEmpty()) {
184	            points += 2;
185	        }
186	        Integer namesakeCount = owner.getNamesakeCount();
187	        if (namesakeCount != null && namesakeCount == 0) {
188	            points += 1;
189	        }
190	        Integer householdMemberCount = owner.getHouseholdMemberCount();
191	        if (householdMemberCount != null && householdMemberCount >= 3) {
192	            points += 2;
193	        }
194	        LocalDate registrationDate = owner.getRegistrationDate();
195	        if (registrationDate != null) {
196	            int tenure = RegistrationDateNormalizer.fiscalYear(LocalDate.now())
197	                - RegistrationDateNormalizer.fiscalYear(registrationDate);
198	            if (tenure > 1) {
199	                points += 3;
200	            }
201	        }
202	        return points;
203	    }
