211	        if (owner == null) {
212	            return null;
213	        }
214	        int points = membershipPoints(owner);
215	        if (points <= 1) {
216	            return 1;
217	        }
218	        if (points <= 3) {
219	            return 2;
220	        }
221	        if (points <= 5) {
222	            return 3;
223	        }
224	        return 4;
225	    }
226	
227	    /**
228	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
