233	        if (owner == null) {
234	            return null;
235	        }
236	        String code = owner.getCustomerCode();
237	        if (code == null) {
238	            return "UNKNOWN";
239	        }
240	        int dash = code.indexOf('-');
241	        return dash >= 0 ? code.substring(0, dash) : code;
242	    }
243	
244	    /**
245	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
246	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
247	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
248	     */
249	    default String timezone(Owner owner) {
250	        if (owner == null) {
251	            return null;
252	        }
253	        String region = locality(owner);
254	        return switch (region) {
255	            case "NSW" -> "Australia/Sydney";
256	            case "VIC" -> "Australia/Melbourne";
257	            case "QLD" -> "Australia/Brisbane";
258	            default -> null;
259	        };
260	    }
261	
262	    /**
263	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
264	     * on its registration day at creation time). A {@code null} stored value is treated as
265	     * {@code false}, so the field is always present in the response.
266	     */
