289	     * present, otherwise {@code PHONE}.
290	     */
291	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
292	        if (owner == null) {
293	            return null;
294	        }
295	        String email = owner.getEmail();
296	        return (email != null && !email.isEmpty())
297	            ? OwnerDto.ContactPreferenceEnum.EMAIL
298	            : OwnerDto.ContactPreferenceEnum.PHONE;
299	    }
300	
301	    /**
302	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
