309	    /**
310	     * Derives the owner's {@code ageBand} from {@code birthDate}, measured as of the owner's
311	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
312	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
313	     * no reference registration date is available), so the field is absent from the response.
314	     */
315	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
316	        if (owner == null || owner.getBirthDate() == null) {
317	            return null;
318	        }
319	        LocalDate reference = owner.getRegistrationDate();
320	        if (reference == null) {
321	            reference = LocalDate.now();
322	        }
323	        int age = Period.between(owner.getBirthDate(), reference).getYears();
324	        if (age < 18) {
325	            return OwnerDto.AgeBandEnum.MINOR;
326	        }
327	        if (age < 65) {
328	            return OwnerDto.AgeBandEnum.ADULT;
329	        }
330	        return OwnerDto.AgeBandEnum.SENIOR;
331	    }
332	
333	    /**
334	     * Derives the owner's {@code selfLink}, the canonical API path for the owner, formed as
335	     * {@code '/api/owners/'} followed by the owner's id. Returns {@code null} until the owner
336	     * has an id, so the field is absent from the response.
337	     */
338	    default String selfLink(Owner owner) {
339	        if (owner == null || owner.getId() == null) {
340	            return null;
341	        }
342	        return "/api/owners/" + owner.getId();
343	    }
344	
345	    @Mapping(target = "id", ignore = true)
346	    @Mapping(target = "pets", ignore = true)
347	    Owner toOwner(OwnerFieldsDto ownerDto);
348	
349	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
350	
351	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
352	
353	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
354	        OwnerPageDto ownerPageDto = new OwnerPageDto();
355	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
356	        ownerPageDto.setPage(ownerPage.getNumber());
357	        ownerPageDto.setSize(ownerPage.getSize());
358	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
359	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
360	        return ownerPageDto;
361	    }
362	}
